replacement_files.tests/fixtures/amd_track3/demo_one.py:
def normalize_name(value: str) -> str:
    """Return a title-cased name and reject blank input."""
    cleaned = value.strip()
    if not cleaned:
        raise ValueError("name must not be blank")
    return cleaned.title()

